class Solution:

	def nQueen(self, n):
		board = [[0 for _ in range(n)] for _ in range(n)]
		ans = []
		self.solveQueen(0, n, board, ans)
		return ans

	def solveQueen(self, row, n, board, ans):
		if row == n:
			temp = []
			for r in range(n):
				for c in range(n):
					if board[r][c] == 1:
						temp.append(c + 1)
			ans.append(temp)
			return
		for col in range(n):
			if self.isSafe(row, col, board, n):
				board[row][col] = 1
				self.solveQueen(row + 1, n, board, ans)
				board[row][col] = 0

	def isSafe(self, row, col, board, n):
		i = 0
		while i < row:
			if board[i][col]:
				return False
			i += 1
		i = row
		j = col
		while i >= 0 and j >= 0:
			if board[i][j]:
				return False
			j -= 1
			i -= 1
		i = row
		j = col
		while i >= 0 and j < n:
			if board[i][j]:
				return False
			j += 1
			i -= 1
		return True
